if(await Bun.file("Taskfile.ts").exists()){let o=await import("./Taskfile.ts");if(Bun.argv.length>=3){let e=Bun.argv[2];if(e in o){let t=o[e];if(t.deps)for(let s of t.deps)await o[s]();await t()}else console.error(`Task not found: ${e}`)}else console.log("Available tasks:"),Object.keys(o).filter(e=>typeof o[e]=="function").forEach(e=>{let t=o[e].desc;console.log(t?`* ${e} - ${t}`:`* ${e}`)})}else console.error("Taskfile.ts not found");
